<template>
  <section class="membership-review-controls" aria-label="Membership prototype states">
    <h3>会员与权益用量 · 一体化入口</h3><p>Free + 单一 Premium。两种身份常规用量都有限；无限量仅为限时活动，活动结束不改变会员身份。购买和续订仅切换原型，不下单；价格与日期为评审样例。</p>
    <label for="membership-preview-state">身份与有效状态</label><select id="membership-preview-state" :value="$route.query.membershipState||'account'" @change="setState($event.target.value)"><option value="account">当前演示账号</option><option value="free">Free · 从未订阅</option><option value="active">Premium · 有效 / 自动续订</option><option value="canceled">Premium · 有效 / 已关续订</option><option value="expired">Free · Premium 已过期</option></select>
    <template v-if="finite"><label for="chat-preview-range">对话剩余额度 · {{ percent }}%</label><input id="chat-preview-range" type="range" min="0" max="100" step="1" :value="percent" @input="setPercent($event.target.value)"><div class="membership-review-presets"><button v-for="n in [0,10,50,100]" :key="n" type="button" :aria-pressed="percent===n?'true':'false'" @click="setPercent(n)">{{ n }}%</button></div></template>
    <label for="allowance-preview-mode">用量／活动状态（独立于会员）</label><select id="allowance-preview-mode" :value="$route.query.allowanceMode||'standard'" :disabled="!$route.query.membershipState" @change="setMode($event.target.value)"><option value="standard">常规 · 有限额度</option><option value="campaign">限时无限量活动 · 进行中</option><option value="ended">无限量活动已结束 · 恢复额度</option></select>
    <p v-if="$route.query.allowanceMode==='campaign'">限时无限量 · 活动截止 Oct 23, 2026。会员身份保持独立。</p>
    <template v-if="pageOptions.length"><label for="mvp-page-state">当前页面状态</label><select id="mvp-page-state" :value="$route.query.mvpState||'default'" @change="setPage($event.target.value)"><option v-for="option in pageOptions" :key="option[0]" :value="option[0]">{{ option[1] }}</option></select><p>保留原页面、入口和弹层。新增 Free 内容与 AI 回复是本地评审样例，不写入训练、订单或用量。</p></template>
    <label for="mvp-purchase-outcome">平台购买结果 · 仅评审</label><select id="mvp-purchase-outcome" :value="purchaseOutcome" @change="$emit('purchase-outcome',$event.target.value)"><option value="success">购买确认成功</option><option value="cancelled">用户取消付款</option><option value="failure">付款失败</option><option value="pending">订单待确认</option></select>
    <router-link :to="{path:$route.path,query:{...$route.query,review:'0'}}">打开纯页面预览 ↗</router-link>
  </section>
</template>
<script>
export default {props:{purchaseOutcome:{type:String,default:'success'},pageOptions:{type:Array,default:()=>[]},member:{type:Object,default:()=>({})}},computed:{finite(){return !!this.$route.query.membershipState&&this.$route.query.allowanceMode!=='campaign'},percent(){return Number(this.$route.query.chatRemaining||0)}},methods:{setPage(state){this.$router.replace({path:this.$route.path,query:{...this.$route.query,membershipState:this.$route.query.membershipState||this.member.state||'free',chatRemaining:this.$route.query.chatRemaining||'65',mvpState:state==='default'?undefined:state}},()=>{})},setState(state){const query={...this.$route.query};delete query.membershipCycle;if(state==='account'){delete query.membershipState;delete query.chatRemaining;delete query.allowanceMode;delete query.mvpState}else{query.membershipState=state;query.chatRemaining=query.chatRemaining||'65'}this.$router.replace({path:this.$route.path,query},()=>{})},setMode(mode){this.$router.replace({path:this.$route.path,query:{...this.$route.query,allowanceMode:mode}},()=>{})},setPercent(value){this.$router.replace({path:this.$route.path,query:{...this.$route.query,chatRemaining:String(value)}},()=>{})}}}
</script>
<style scoped>
.membership-review-controls{padding:16px 12px;margin:16px 0;border:1px solid #738298;border-radius:12px;background:#ffffff09}.membership-review-controls h3{font-size:15px;margin:0 0 8px;color:#fff}.membership-review-controls p{font-size:12px;line-height:1.7;color:#d2deed;margin:8px 0}.membership-review-controls label{display:block;font-size:12px;margin:12px 0 6px}.membership-review-controls input{width:100%;accent-color:#ffb49e}.membership-review-controls a{font-size:12px;color:#fff;display:block;margin-top:12px}.membership-review-presets{display:flex;gap:6px}.membership-review-presets button{flex:1;min-height:32px;border:1px solid #8a98ac;border-radius:6px;background:transparent;color:#fff;cursor:pointer}.membership-review-presets button[aria-pressed=true]{background:#fff;color:#263548}
</style>
